import type * as React from 'react'
import type {EntryPointProps} from 'react-relay'

import {useQueryParam} from '../../../hooks/routes'
import {useSetUserProperty} from '../../../hooks/useSetUserProperty'
import {useBooleanUserProperty} from '../../../hooks/useUserProperty'
import {UserProperties} from '../../../utils/userProperties'

import ToggleSakuraUI from './ToggleSakuraUI'
import type {OpenInSakuraUIProps} from './ToggleSakuraUI.types'
import {getSakuraUIHref} from './ToggleSakuraUI.utils'

export default function OpenInSakuraUI({
  props,
}: EntryPointProps<{}, {}, OpenInSakuraUIProps, {}>): React.ReactElement | null {
  const isFirstTimeSakuraUI = !useBooleanUserProperty(UserProperties.HAS_SEEN_EXPERIMENTAL_OVERVIEW)
  const onlyModified = useQueryParam('onlyModified')

  const href = getSakuraUIHref({...props, onlyModified})
  const setUserProperty = useSetUserProperty()
  return href != null ? (
    <ToggleSakuraUI
      className={props.className}
      turnOn
      href={href}
      onConditionalClick={
        isFirstTimeSakuraUI
          ? isPlainLeft => {
              if (isPlainLeft) {
                setUserProperty(UserProperties.USE_EXPERIMENTAL_OVERVIEW, 'true')
              }
            }
          : undefined
      }
    />
  ) : null
}
