import Link from '@jetbrains/ring-ui-built/components/link/link'
import {SvgIcon} from '@jetbrains/teamcity-ui/dist/components'
import classNames from 'classnames'
import * as React from 'react'

import {useSakuraReleaseBanner} from '../../classic/SakuraReleaseBanner/SakuraReleaseBanner.hooks'

import type {Props} from './ToggleSakuraUI.types'

import styles from './ToggleSakuraUI.module.css'

const ToggleSakuraUI: React.ComponentType<Props> = React.memo(function ToggleSakuraUI({
  turnOn,
  href,
  className,
  onConditionalClick,
  children,
}) {
  const showReleaseBanner = useSakuraReleaseBanner()
  return href != null ? (
    <div className={styles.container}>
      {children}
      {!showReleaseBanner || !turnOn ? (
        <Link
          href={href}
          title={`Switch to ${turnOn ? 'Sakura' : 'Classic'} UI`}
          className={classNames(styles.link, className, {
            [styles.turnOn]: turnOn,
          })}
          onConditionalClick={onConditionalClick}
        >
          <div className={styles.triangle} />
          <SvgIcon icon={turnOn ? 'magic-wand-12px' : 'mammoth-12px'} className={styles.icon} />
        </Link>
      ) : null}
    </div>
  ) : null
})
export default ToggleSakuraUI
